@pytest.fixture()
def fake(monkeypatch: pytest.MonkeyPatch) -> Fake:
    f = Fake()
    monkeypatch.setattr(tickets, "gh", f)
    monkeypatch.setattr(approval, "gh", f)
    monkeypatch.delenv("GITHUB_REPOSITORY", raising=False)
    return f


def hub(root: Path) -> tickets.Hub:
    h = tickets.Hub(REPO)
    h.root = root
    return h


def ticket(f: Fake, role: str, labels: list[str] | None = None) -> int:
    body = tickets.ticket_body(role, "goal", "", "", None, [], "product")
    return f.make("work", body, ["ticket", f"role:{role}", *(labels or [])])


def test_gaps_name_the_current_stage_the_uncovered_initiative_and_a_key_result_without_one(root: Path) -> None:
    found = {g["key"]: g["what"] for g in autopilot.gaps(root, [], NOW.date())}
    assert set(found) == {"stage:13", "initiative:I1", "kr:O1.2"}
    assert "Definition of done met" in found["stage:13"]
    assert autopilot.next_slice(root) == "S2 Billing"


def test_open_tickets_with_the_label_cover_a_gap(root: Path) -> None:
    covering = [{"labels": [{"name": "stage:13"}]}, {"labels": [{"name": "initiative:I1"}]}]
    assert [g["key"] for g in autopilot.gaps(root, covering, NOW.date())] == ["kr:O1.2"]


def test_plan_opens_one_planning_ticket_for_the_chief_of_staff(root: Path, fake: Fake) -> None:
    cfg = autopilot.settings(json.loads((root / "founder/heartbeats.json").read_text()))
    made = autopilot.plan(hub(root), root, cfg, NOW)
    assert made and "role:chief-of-staff" in fake.names(made["number"]) and "autopilot-plan" in fake.names(made["number"])
    assert "`stage:13`" in made["body"] and "S2 Billing" in made["body"]
    assert autopilot.plan(hub(root), root, cfg, NOW) is None  # one at a time
    fake.issues[made["number"]].update(state="closed", closed_at="2026-11-24T06:00:00Z")
    assert autopilot.plan(hub(root), root, cfg, NOW) is None  # not again within plan_every_hours


def test_due_starts_roles_with_ready_work_inside_their_budget(root: Path, fake: Fake) -> None:
    pol = json.loads((root / "founder/heartbeats.json").read_text())
    eng = ticket(fake, "engineer")
    ticket(fake, "qa")                            # qa has no budget: never starts
    ticket(fake, "growth")                        # growth's heartbeat is off
    ticket(fake, "engineer", [tickets.BLOCKED])  # blocked work doesn't count
    roles, why = autopilot.due(hub(root), root, pol, NOW)
    started = {r["role"]: r for r in roles}
    assert set(started) == {"engineer", "chief-of-staff"}, why  # chief of staff: the planning ticket it just got
    assert started["engineer"]["model"] == "sonnet" and "heartbeat.py start engineer" in started["engineer"]["prompt"]
    assert any(line.startswith("qa: no budget") for line in why)
    assert any(line.startswith("growth: heartbeat off") for line in why)
    assert f"ready #{eng}" in " ".join(why)


def test_due_does_nothing_while_the_autopilot_is_off(root: Path, fake: Fake) -> None:
    ticket(fake, "engineer")
    roles, why = autopilot.due(hub(root), root, {"roles": {"engineer": {"enabled": True}}}, NOW)
    assert roles == [] and "autopilot is off" in why[0]
    assert not any("autopilot-plan" in fake.names(n) for n in fake.issues)


def test_due_skips_a_role_with_a_run_active(root: Path, fake: Fake) -> None:
    pol = json.loads((root / "founder/heartbeats.json").read_text())
    ticket(fake, "engineer")
    fake.refs["refs/heartbeats/engineer"] = "k9"
    fake.commits["k9"] = {"sha": "k9", "message": f"heartbeat engineer at {NOW.timestamp() - 60}"}
    roles, why = autopilot.due(hub(root), root, pol, NOW)
    assert "engineer" not in {r["role"] for r in roles}
    assert "engineer: a run is active" in why


def test_due_writes_the_matrix_only_with_an_agent_token(root: Path, fake: Fake, tmp_path: Path,
                                                       monkeypatch: pytest.MonkeyPatch) -> None:
    ticket(fake, "engineer")
    out = tmp_path / "out.txt"
    monkeypatch.setenv(autopilot.TOKEN_ENV, "false")
    assert autopilot.main(["due", "--root", str(root), "--github-output", str(out), "--now", str(NOW.timestamp())]) == 0
    assert "run=no" in out.read_text()
    out.write_text("")
    monkeypatch.setenv(autopilot.TOKEN_ENV, "true")
    autopilot.main(["due", "--root", str(root), "--github-output", str(out), "--now", str(NOW.timestamp())])
    text = out.read_text()
    assert "run=yes" in text and '"role": "engineer"' in text and "parallel=2" in text


def test_tickets_new_takes_a_stage_label_and_inherits_it(root: Path, fake: Fake) -> None:
    (root / "founder/goals.json").write_text("{}", encoding="utf-8")
    assert tickets.main(["new", "engineer", "--title", "t", "--goal", "g", "--stage", "13", "--by", "chief-of-staff",
                         "--root", str(root)]) == 0
    parent = max(n for n in fake.issues if "ticket" in fake.names(n))
    assert "stage:13" in fake.names(parent)
    tickets.main(["new", "qa", "--title", "t2", "--goal", "g", "--parent", str(parent), "--by", "engineer",
                  "--root", str(root)])
    child = max(n for n in fake.issues if "ticket" in fake.names(n))
    assert child != parent and "stage:13" in fake.names(child)


def test_notify_mentions_the_founder_once_per_new_item_and_sends_one_digest_a_day(root: Path, fake: Fake) -> None:
    items = [{"kind": "approval", "title": "Deploy S2", "url": "https://github.com/acme/x/issues/4", "number": 4,
              "level": "new", "detail": "deploy gate"},
             {"kind": "blocked", "title": "#7 Billing", "url": "", "number": 7, "level": "overdue", "detail": "on #6"}]
    h = hub(root)
    sent = notify.push(root, h, items, NOW, "off")
    n = sent["issue"]
    assert sent["new"] == 2 and "needs-you" in fake.names(n)
    assert fake.comments[n][-1]["body"].startswith("@acme 2 new things")
    assert notify.push(root, h, items, NOW, "off")["new"] == 0  # already announced
    assert len(fake.comments[n]) == 1
    sent = notify.push(root, h, items, NOW.replace(hour=7), "auto")
    assert sent["digest"] and "Daily digest: 2 things" in fake.comments[n][-1]["body"]
    fake.comments[n][-1]["created_at"] = NOW.isoformat()
    assert not notify.push(root, h, items, NOW.replace(hour=7), "auto")["digest"]  # once a day
    assert not notify.push(root, h, items, NOW.replace(hour=9), "auto")["digest"]  # still once a day
    assert not notify.push(root, h, items, NOW.replace(day=25, hour=6), "auto")["digest"]  # not before its hour
    fake.comments[n][-1]["created_at"] = NOW.replace(day=25).isoformat()
    assert notify.push(root, h, items, NOW.replace(day=25, hour=9), "auto")["digest"]  # the first run after it
    assert notify.push(root, h, [], NOW, "auto")["new"] == 0
    assert "Nothing waits on you." in fake.issues[n]["body"]


def test_a_ticket_blocked_for_a_day_shows_in_needs_you() -> None:
    import build_dashboard as bd
    old = (NOW - dt.timedelta(hours=30)).isoformat()
    fresh = (NOW - dt.timedelta(hours=2)).isoformat()
    data = {"repo": {}, "github": {"ok": True, "approvals": [], "costs": {}, "tickets": [
        {"number": 7, "title": "Billing", "url": "", "role": "engineer", "blocked": True, "blocked_by": [6],
         "updated": old, "claimed": False},
        {"number": 8, "title": "Fresh", "url": "", "role": "qa", "blocked": True, "blocked_by": [7], "updated": fresh}]}}
    needs = bd.needs_you(data, NOW)
    blocked = [x for x in needs["items"] if x["kind"] == "blocked"]
    assert [x["number"] for x in blocked] == [7] and "on #6" in blocked[0]["detail"]
    assert needs["counts"]["blocked"] == 1


def test_due_asks_the_founder_once_for_a_plan_nobody_requested(root: Path, fake: Fake) -> None:
    (root / "founder/gates.json").write_text(json.dumps({"founders": [], "gates": {
        "plan": {"mode": "ask", "what": "Start a plan", "paths": []}}}), encoding="utf-8")
    pol = json.loads((root / "founder/heartbeats.json").read_text())
    parent = ticket(fake, "chief-of-staff", ["stage:13", "initiative:I1", "kr:O1.2"])
    body = tickets.ticket_body("engineer", "goal", "", "", parent, [], "chief-of-staff")
    fake.make("child", body, ["ticket", "role:engineer"])
    roles, why = autopilot.due(hub(root), root, pol, NOW)
    plans = [n for n in fake.issues if "gate:plan" in fake.names(n)]
    assert len(plans) == 1 and f"plan: asked the founder to approve #{parent}'s plan" in why
    assert "engineer" not in {r["role"] for r in roles}  # still waits for the approval
    autopilot.due(hub(root), root, pol, NOW)
    assert len([n for n in fake.issues if "gate:plan" in fake.names(n)]) == 1  # once


def test_the_goal_tree_gap_is_covered_by_its_label(root: Path) -> None:
    (root / "founder/goals.json").write_text("{}", encoding="utf-8")
    (root / "founder/playbook.md").write_text(PLAYBOOK.replace("| Passed |", "| Passed |\n| 3 | B | Business model | P | ok |  | Passed |"),
                                              encoding="utf-8")
    keys = [g["key"] for g in autopilot.gaps(root, [{"labels": [{"name": "stage:13"}]}], NOW.date())]
    assert keys == ["goal-tree"]
    assert autopilot.gaps(root, [{"labels": [{"name": "stage:13"}, {"name": "goal-tree"}]}], NOW.date()) == []


def run(role: str, outcome: str, minutes_ago: float, ticket: int | None = None) -> dict[str, object]:
    at = (NOW - dt.timedelta(minutes=minutes_ago)).strftime("%Y-%m-%dT%H:%M:%SZ")
    return {"role": role, "outcome": outcome, "ticket": ticket, "at": at, "usd": 0.0, "session": ""}


def test_an_escalated_ticket_does_not_start_its_role_again(root: Path, fake: Fake) -> None:
    pol = json.loads((root / "founder/heartbeats.json").read_text())
    ticket(fake, "engineer", [tickets.ESCALATED + "founder"])
    roles, why = autopilot.due(hub(root), root, pol, NOW)
    assert "engineer" not in {r["role"] for r in roles}
    assert "engineer: nothing ready" in why


def test_a_ticket_that_just_stalled_waits_before_a_retry() -> None:
    runs = [run("engineer", "blocked", 30, 7), run("engineer", "worked", 20, 8), run("engineer", "failed", 600, 9),
            run("qa", "blocked", 10, 8)]
    assert autopilot.stalled(runs, "engineer", NOW) == {7}  # 8 worked last; 9 stalled too long ago


def test_a_role_whose_last_run_did_nothing_waits_an_hour() -> None:
    assert autopilot.idle_recently([run("qa", "worked", 90, 3), run("qa", "no-work", 20)], "qa", NOW)
    assert not autopilot.idle_recently([run("qa", "no-work", 90)], "qa", NOW)
    assert not autopilot.idle_recently([run("qa", "no-work", 20), run("qa", "worked", 5, 3)], "qa", NOW)


def test_every_run_today_counts_toward_the_cap() -> None:
    runs = [run("qa", "no-work", 10), run("engineer", "worked", 20, 1), run("qa", "no-work", 60 * 24)]
    assert autopilot.runs_today(None, NOW, runs) == 2  # type: ignore[arg-type]


def test_finish_does_not_count_a_run_twice_when_the_agent_logged_a_wrong_link() -> None:
    runs = [run("qa", "worked", 3, 30)]
    assert autopilot.logged_lately(runs, "qa", "https://github.com/o/r/actions/runs/9", NOW)
    assert not autopilot.logged_lately(runs, "engineer", "https://github.com/o/r/actions/runs/9", NOW)
    assert not autopilot.logged_lately([run("qa", "worked", 120, 30)], "qa", "https://github.com/o/r/actions/runs/9", NOW)
